583	  async function send(overrideText?: string, image?: string) {
584	    const text = (overrideText ?? prompt).trim();
585	    if (!text || busy) return;
586	    if (balance <= 0) {
587	      setError("You're out of credits. Top up to keep building.");
588	      return;
589	    }
590	
591	    setBusy(true);
592	    setError(null);
593	    setInterruption(null);
594	    setWroteFiles(false);
595	    setStatus(isFirstBuild ? "Building your site…" : "Applying your changes…");
596	    setMessages((m) => [...m, { role: "user", content: text }]);
597	    setPrompt("");
598	    setEnhancedFrom(null);
599	    streamingReply.current = "";
600	    stopRequested.current = false;
601	    const controller = new AbortController();
602	    abortRef.current = controller;
603	
604	    // Set once the first byte of the stream lands. After that point any
605	    // failure is the connection, not the request — which is what lets us tell
606	    // "couldn't start" apart from "died halfway".
607	    let streamStarted = false;
608	    // A `done` or `error` event. The route always sends one of them unless it
609	    // saw the client go away, so a stream that closes without either IS the
610	    // signature of a dropped connection.
611	    let sawTerminal = false;
612	    let touchedFiles = false;
613	    // The checkpoint this build created, once it has actually succeeded. Read
614	    // after the stream to move the undo cursor — a state setter can't be read
615	    // back here, and an interrupted build never reaches the `done` event, so
616	    // this is also what keeps a failed build from moving the cursor.
617	    let finishedBuildId: string | null = null;
618	
619	    try {
620	      const res = await fetch("/api/generate", {
621	        method: "POST",
622	        headers: { "Content-Type": "application/json" },
623	        body: JSON.stringify({ projectId: props.projectId, prompt: text, image }),
624	        signal: controller.signal,
625	      });
626	
627	      if (!res.ok || !res.body) {
628	        const body = await res.json().catch(() => ({}));
629	        throw new Error(body?.error ?? "The build failed to start.");
630	      }
631	
632	      const reader = res.body.getReader();
633	      const decoder = new TextDecoder();
634	      let buffer = "";
635	
636	      while (true) {
637	        const { done, value } = await reader.read();
638	        if (done) break;
639	        streamStarted = true;
640	        buffer += decoder.decode(value, { stream: true });
641	
642	        const parts = buffer.split("\n\n");
643	        buffer = parts.pop() ?? "";
644	
645	        for (const part of parts) {
646	          if (!part.startsWith("data: ")) continue;
647	          const event = JSON.parse(part.slice(6));
648	
649	          if (event.type === "text") {
650	            streamingReply.current += event.text;
651	          } else if (event.type === "progress" || event.type === "status") {
652	            // Both drive the same line. `progress` comes from a real tool call,
653	            // `status` from a phase the route knows about (a repair pass).
654	            setStatus(event.text);
655	          } else if (event.type === "file") {
656	            // On the SDK engine these all arrive at once after the build, so
657	            // they are a completion signal, not live progress — the progress
658	            // line above is what the user actually watches. On the `api`
659	            // engine they arrive one per write, which is what makes them
660	            // usable as evidence that a stopped build left files behind.
661	            touchedFiles = true;
662	            setWroteFiles(true);
663	          } else if (event.type === "done") {
664	            sawTerminal = true;
665	            setBalance(event.remaining);
666	            setStatus(null);
667	            finishedBuildId = event.buildId ?? null;
668	            setLastBuildId(finishedBuildId);
669	          } else if (event.type === "error") {
670	            sawTerminal = true;
671	            throw new BuildServerError(event.message);
672	          }
673	        }
674	      }
675	
676	      if (!sawTerminal) {
677	        // The pipe closed mid-build. Nothing was thrown, no error arrived —
678	        // this is exactly the silent stop the user used to be left staring at.
679	        setInterruption("connection-lost");
680	      } else if (streamingReply.current.trim()) {
681	        // Only on a build that actually completed: the route persists the
682	        // assistant reply in the success branch alone, so showing it after an
683	        // interruption would put a message on screen that a reload deletes.
684	        setMessages((m) => [...m, { role: "assistant", content: streamingReply.current.trim() }]);
685	      }
686	      // Deliberately swallowed. This runs AFTER the stream has closed cleanly,
687	      // so the build is already over and its outcome already decided — letting
688	      // a failed re-fetch fall into the catch below would report a finished
689	      // build as a lost connection, which is the one thing that block must
690	      // never say wrongly. A stale file list is a reload away; a false
691	      // "connection lost" sends the user hunting for a problem that isn't
692	      // there.
693	      if (touchedFiles) await refreshFiles().catch(() => {});
694	      if (finishedBuildId) {
695	        // A new checkpoint. The draft matches it exactly, and whatever the user
696	        // had stepped back from is no longer reachable going forward — they
697	        // built something else instead, which is what clears a redo stack in
698	        // every editor that has one.
699	        //
700	        // Swallowed for the same reason as the refresh above: the build is over
701	        // and its outcome decided. A failed refresh leaves the list without the
702	        // new checkpoint, which the undo control reports honestly as "the
703	        // checkpoint this draft came from has been cleared" rather than
704	        // offering a wrong step.
705	        setCursor(finishedBuildId);
706	        setDirty(false);
707	        setRedoStack([]);
708	        await refreshCheckpoints().catch(() => {});
709	      }
710	    } catch (err) {
711	      if (stopRequested.current) {
712	        setInterruption("stopped");
713	        // Files the agent wrote before the abort are already committed to the
714	        // draft source, so pull them in — the Code view should show what is
715	        // really there, half-finished or not.
716	        if (touchedFiles) await refreshFiles().catch(() => {});
717	      } else if (err instanceof BuildServerError) {
718	        setError(err.message);
719	      } else if (streamStarted) {
720	        setInterruption("connection-lost");
721	      } else {
722	        setError(err instanceof Error ? err.message : "Something went wrong.");
723	      }
724	    } finally {
725	      abortRef.current = null;
726	      stopRequested.current = false;
727	      setStopping(false);
728	      setBusy(false);
729	      setStatus(null);
730	    }
731	  }
