747	  // the JSON error body as "slug.zip".
748	  async function downloadZip() {
749	    setDownloading(true);
750	    setError(null);
751	    try {
752	      const res = await fetch(`/api/projects/${props.projectId}/export`);
753	      if (!res.ok) {
754	        const body = await res.json().catch(() => ({}));
755	        throw new Error(body?.error ?? "Download failed.");
756	      }
757	      const url = URL.createObjectURL(await res.blob());
