812	  // Global shortcuts. Deliberately three, all of them either an established
813	  // convention (⌘K / ⌃⇧P for a palette, "/" to jump to the input) or a
814	  // disambiguation of a key the box already owns (⌘⏎ builds even when Enter
815	  // has been handed over to the spec editor). Anything more inventive would
816	  // be a shortcut nobody discovers and everybody triggers by accident.
817	  // Bound only while the palette is CLOSED. While it is open the dialog owns
818	  // the keyboard outright — that is what makes the focus trap and the Escape
819	  // handling airtight, and it saves reading a "is it open" ref during render.
820	  useEffect(() => {
821	    if (paletteOpen) return;
822	    function onKeyDown(e: KeyboardEvent) {
823	      const mod = e.metaKey || e.ctrlKey;
824	      const openWith = (opener: HTMLElement | null) => {
825	        paletteReturn.current = opener;
826	        setPaletteOpen(true);
827	      };
828	      const active = document.activeElement;
829	      const focused = active instanceof HTMLElement && active !== document.body ? active : null;
830	
831	      if (mod && !e.altKey && e.key.toLowerCase() === "k") {
832	        e.preventDefault();
833	        openWith(focused);
834	        return;
835	      }
836	      if (mod && e.shiftKey && e.key.toLowerCase() === "p") {
837	        e.preventDefault();
