43	  loading,
44	  error,
45	  reloadKey,
46	  device,
47	  onDeviceChange,
48	  frameRef,
49	  selectMode,
50	  selectAvailable,
51	  onToggleSelectMode,
52	}: {
53	  /** The assembled document, or null before the first load finishes. */
