3	import { useState } from "react";
4	import type { BuildDiff, FileDiff, Hunk } from "./diff";
5	
6	// What one build changed, file by file and line by line.
7	//
8	// HONESTY NOTE, and it is the whole reason the copy in here is worded the way
9	// it is: by the time anyone can look at this screen the build has already
10	// written to the database and the preview is already showing the new site.
11	// This is NOT an approval gate. There is no state in which the change is
12	// pending. So the two controls are "Undo this build" — which restores the
13	// previous checkpoint, a new write, not a cancellation — and "Close", which
14	// does nothing at all because there is nothing to accept. Calling those
15	// "Approve" and "Reject" would describe a mechanism that does not exist.
16	//
17	// Accessibility:
18	//  - the +/- gutter marker is real text, not colour and not aria-hidden, so a
19	//    screen reader reads "plus <line>" and the add/remove distinction does not
20	//    live in the pixels alone. Line numbers ARE hidden, because reading two
21	//    numbers before every line makes the diff unlistenable.
22	//  - each file is a disclosure button with aria-expanded/aria-controls.
23	//  - no aria-live anywhere in this file. The editor already has exactly one
24	//    live region (the build progress line) and a second one competing with it
25	//    is a bug this file has been bitten by before.
26	
27	const FOCUS_RING =
28	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
29	
30	/** Expand everything up front only while the whole diff is small enough to scan. */
31	const AUTO_EXPAND_LINES = 400;
32	
33	function statusLabel(status: FileDiff["status"]): string {
34	  return status === "added" ? "Added" : status === "removed" ? "Removed" : "Changed";
35	}
36	
37	function countLabel(file: FileDiff): string {
38	  if (file.status === "added") return `${file.added} line${file.added === 1 ? "" : "s"}`;
39	  if (file.status === "removed") return `${file.removed} line${file.removed === 1 ? "" : "s"}`;
40	  return `+${file.added} −${file.removed}`;
41	}
42	
43	function FileCounts({ file }: { file: FileDiff }) {
44	  return (
45	    <span className="flex shrink-0 items-center gap-2 text-xs">
46	      <span className="text-black/45 dark:text-white/45">{statusLabel(file.status)}</span>
47	      <span
48	        className={
49	          file.status === "removed"
50	            ? "text-red-700 dark:text-red-400"
51	            : file.status === "added"
52	              ? "text-emerald-700 dark:text-emerald-400"
53	              : "text-black/55 dark:text-white/55"
54	        }
55	      >
56	        {countLabel(file)}
57	      </span>
58	    </span>
59	  );
60	}
61	
62	function HunkBlock({ hunk }: { hunk: Hunk }) {
63	  return (
64	    <div className="border-t border-black/10 dark:border-white/10">
65	      <div
66	        className="bg-black/[0.03] px-3 py-1 font-mono text-[11px] text-black/45 dark:bg-white/[0.04] dark:text-white/45"
67	        aria-hidden="true"
68	      >
69	        @@ −{hunk.aStart},{hunk.aCount} +{hunk.bStart},{hunk.bCount} @@
70	      </div>
71	      <div className="overflow-x-auto">
72	        {hunk.lines.map((line, i) => (
73	          <div
74	            key={i}
75	            className={`flex min-w-max font-mono text-[11.5px] leading-[1.45] ${
76	              line.op === "add"
77	                ? "bg-emerald-500/10 text-emerald-800 dark:text-emerald-300"
78	                : line.op === "remove"
79	                  ? "bg-red-500/10 text-red-800 dark:text-red-300"
80	                  : "text-black/60 dark:text-white/60"
81	            }`}
82	          >
83	            <span
84	              aria-hidden="true"
85	              className="w-10 shrink-0 select-none pr-2 text-right text-black/30 dark:text-white/30"
86	            >
87	              {line.a ?? ""}
88	            </span>
89	            <span
90	              aria-hidden="true"
91	              className="w-10 shrink-0 select-none pr-2 text-right text-black/30 dark:text-white/30"
92	            >
93	              {line.b ?? ""}
94	            </span>
95	            {/* Read out loud. This is the only non-visual carrier of "added"
96	                vs "removed", so it must not be hidden from assistive tech. */}
97	            <span className="w-4 shrink-0 select-none">
98	              {line.op === "add" ? "+" : line.op === "remove" ? "−" : " "}
99	            </span>
100	            <span className="whitespace-pre pr-4">{line.text === "" ? " " : line.text}</span>
101	          </div>
102	        ))}
103	      </div>
104	    </div>
105	  );
106	}
