108	export default function DiffView({
109	  diff,
110	  onUndo,
111	  undoUnavailable,
112	  undoing,
113	  onClose,
114	}: {
115	  diff: BuildDiff;
116	  /** Restore the previous checkpoint. Null when that is not a truthful offer. */
117	  onUndo: (() => void) | null;
118	  /** Why undo is not offered, when it is not. Shown verbatim. */
119	  undoUnavailable: string | null;
120	  undoing: boolean;
121	  onClose: () => void;
122	}) {
123	  const total = diff.files.reduce(
124	    (sum, f) => sum + f.hunks.reduce((n, h) => n + h.lines.length, 0),
125	    0,
126	  );
127	  const [open, setOpen] = useState<Set<string>>(
128	    () => new Set(total <= AUTO_EXPAND_LINES ? diff.files.map((f) => f.path) : []),
129	  );
130	
131	  function toggle(path: string) {
132	    setOpen((current) => {
133	      const next = new Set(current);
134	      if (next.has(path)) next.delete(path);
135	      else next.add(path);
136	      return next;
137	    });
138	  }
139	
140	  const added = diff.files.reduce((n, f) => n + f.added, 0);
141	  const removed = diff.files.reduce((n, f) => n + f.removed, 0);
142	
143	  return (
144	    <div className="h-full overflow-y-auto p-4">
145	      <div className="mx-auto max-w-3xl">
146	        <h2 className="text-sm font-medium">What this build changed</h2>
147	        <p className="mt-1 text-sm text-black/70 dark:text-white/70">{diff.build.prompt}</p>
148	        <p className="mt-1 text-xs text-black/40 dark:text-white/40">
149	          {new Date(diff.build.createdAt).toLocaleString()}
150	          {diff.previous && (
151	            <>
152	              {" · compared against the checkpoint from "}
153	              {new Date(diff.previous.createdAt).toLocaleString()}
154	            </>
155	          )}
156	        </p>
157	
158	        {/* The two states where "what changed" cannot be answered as a change
159	            set. Both show the whole tree; only one of them is normal. */}
160	        {diff.previousPruned && (
161	          <p className="mt-3 rounded-lg border border-amber-500/40 bg-amber-500/5 px-3 py-2 text-xs text-amber-700 dark:text-amber-400">
162	            The earlier checkpoint&rsquo;s files have been cleared to save storage, so there is
163	            nothing left to compare against. Everything below is the tree as it stood after this
164	            build, not the change this build made.
165	          </p>
166	        )}
167	        {!diff.previous && !diff.previousPruned && (
168	          <p className="mt-3 text-xs text-black/45 dark:text-white/45">
169	            This is the first checkpoint of the project, so every file counts as new.
170	          </p>
171	        )}
172	
173	        <p className="mt-3 text-xs text-black/50 dark:text-white/50">
174	          {diff.files.length === 0
175	            ? "No file changed."
176	            : `${diff.files.length} file${diff.files.length === 1 ? "" : "s"} · +${added} −${removed} lines`}
177	        </p>
178	
179	        {/* Says plainly what this screen is and is not. The board card asked for
180	            approve/reject before applying; there is no before. */}
181	        <div className="mt-3 rounded-lg border border-black/10 px-3 py-2.5 dark:border-white/10">
182	          <p className="text-xs text-black/60 dark:text-white/60">
183	            This build has already been applied — the draft and the preview are showing it now.
184	            Undoing does not cancel it and does not refund its credits; it writes the previous
185	            checkpoint back over the draft, which you can reverse again with Redo.
186	          </p>
187	          <div className="mt-2 flex flex-wrap items-center gap-2">
188	            <button
189	              type="button"
190	              onClick={() => onUndo?.()}
191	              disabled={onUndo === null || undoing}
192	              className={`rounded-lg border border-black/15 px-3 py-1.5 text-xs disabled:opacity-40 dark:border-white/15 ${FOCUS_RING}`}
193	            >
194	              {undoing ? "Undoing…" : "Undo this build"}
195	            </button>
196	            <button
197	              type="button"
198	              onClick={onClose}
199	              className={`rounded-lg border border-black/15 px-3 py-1.5 text-xs dark:border-white/15 ${FOCUS_RING}`}
200	            >
201	              Close
202	            </button>
203	            {onUndo === null && undoUnavailable && (
204	              <span className="text-xs text-black/45 dark:text-white/45">{undoUnavailable}</span>
205	            )}
206	          </div>
207	        </div>
208	
209	        <ul className="mt-4 space-y-2">
210	          {diff.files.map((file, i) => {
211	            const panelId = `kodely-diff-panel-${i}`;
212	            const expanded = open.has(file.path);
213	            return (
214	              <li
215	                key={file.path}
216	                className="overflow-hidden rounded-lg border border-black/10 dark:border-white/10"
217	              >
218	                {/* A truncated file has nothing to disclose, so it gets a plain
219	                    heading rather than a dead disclosure button — aria-expanded
220	                    on something that can never expand is a lie to a screen
221	                    reader, and a disabled control invites a click that does
222	                    nothing. */}
223	                {file.truncated ? (
224	                  <div className="flex w-full items-center justify-between gap-3 px-3 py-2">
225	                    <span className="flex min-w-0 items-center gap-2">
226	                      <span aria-hidden="true" className="w-3 shrink-0" />
227	                      <span className="truncate font-mono text-xs">{file.path}</span>
228	                    </span>
229	                    <FileCounts file={file} />
230	                  </div>
231	                ) : (
232	                  <button
233	                    type="button"
234	                    onClick={() => toggle(file.path)}
235	                    aria-expanded={expanded}
236	                    aria-controls={panelId}
237	                    className={`flex w-full items-center justify-between gap-3 px-3 py-2 text-left ${FOCUS_RING}`}
238	                  >
239	                    <span className="flex min-w-0 items-center gap-2">
240	                      <span
241	                        aria-hidden="true"
242	                        className="w-3 shrink-0 text-xs text-black/35 dark:text-white/35"
243	                      >
244	                        {expanded ? "▾" : "▸"}
245	                      </span>
246	                      <span className="truncate font-mono text-xs">{file.path}</span>
247	                    </span>
248	                    <FileCounts file={file} />
249	                  </button>
250	                )}
251	
252	                {file.approximate && (
253	                  <p className="border-t border-black/10 px-3 py-1.5 text-[11px] text-amber-700 dark:border-white/10 dark:text-amber-400">
254	                    Too much of this file changed to match it line by line, so the changed block is
255	                    shown as removed-then-added rather than aligned.
256	                  </p>
257	                )}
258	                {file.truncated && (
259	                  <p className="border-t border-black/10 px-3 py-1.5 text-[11px] text-black/45 dark:border-white/10 dark:text-white/45">
260	                    Too large to show line by line. The counts above are exact; the full file is in
261	                    the Code view.
262	                  </p>
263	                )}
264	
265	                {/* The panel element exists whether or not it is open, so
266	                    `aria-controls` above always resolves to a real id. Its
