270	                  <div id={panelId} hidden={!expanded}>
271	                    {expanded && file.hunks.map((hunk, h) => <HunkBlock key={h} hunk={hunk} />)}
272	                  </div>
273	                )}
274	              </li>
275	            );
276	          })}
277	        </ul>
278	      </div>
279	    </div>
280	  );
281	}
