1	// Click-to-select for the live preview.
2	//
3	// ---------------------------------------------------------------------------
4	// WHY THIS FILE EXISTS, AND WHY IT LOOKS LIKE THIS
5	//
6	// The preview iframe is sandboxed `allow-scripts allow-forms` WITHOUT
7	// `allow-same-origin` (PreviewFrame.tsx). That is deliberate and stays.
8	// Everything below was verified in real headless Chrome against a server that
9	// reproduced the preview's exact sandbox + CSP, not assumed:
10	//
11	//   * `iframe.contentDocument` is null and `contentWindow.location` throws
12	//     SecurityError. The parent CANNOT read or touch the preview DOM. Any
13	//     design that walks the iframe's DOM from the parent is dead.
14	//   * `contentWindow.postMessage(msg, "*")` DOES reach the frame. Targeting an
15	//     exact origin instead is silently dropped (the frame's origin is opaque),
16	//     and `targetOrigin: "null"` throws SyntaxError. So: always "*".
17	//   * The frame can `parent.postMessage(...)` back. On arrival `event.origin`
18	//     is the *string* "null", which is worthless for authentication —
19	//     `event.source === iframe.contentWindow` is the only real check.
20	//   * Every SUBRESOURCE request made from inside the frame is treated as
21	//     cross-site: `sec-fetch-site: cross-site`, and the session cookie is NOT
22	//     sent. A cookie-authenticated `/api/preview/...` asset therefore 401s.
23	//     There is no header-only fix for that.
24	//
25	// That last point is why this file assembles a SELF-CONTAINED document. The
26	// parent fetches index.html and its assets (same-origin, cookies work fine
27	// there), inlines them, and hands the whole thing to the iframe via `srcdoc`.
28	// Zero subresources means zero cross-site requests, and it gives us the one
29	// thing click-to-select actually needs: a place to inject the agent below.
30	//
31	// The sandbox attribute is untouched. The security policy is re-asserted
32	// in-band by <meta http-equiv> — see PREVIEW_META_CSP.
33	// ---------------------------------------------------------------------------
34	
35	/** Namespaces every message in both directions. Bump if the shape changes. */
36	export const PREVIEW_NS = "kodely-preview:v1";
37	
38	/** Where a selected element sits in the page's top-level landmark run. */
39	export type SelectionSection = {
40	  index: number;
41	  total: number;
42	  tag: string;
43	  id: string | null;
44	  heading: string | null;
45	};
46	
47	/** What the agent reports about a clicked element. All fields are UNTRUSTED. */
48	export type SelectedElement = {
49	  tag: string;
50	  id: string | null;
51	  classes: string | null;
52	  /** Own text if the element has any, otherwise its subtree's text. */
53	  text: string | null;
54	  /** False when `text` came from descendants rather than the element itself. */
55	  textIsOwn: boolean;
56	  path: string;
57	  section: SelectionSection | null;
58	  role: string | null;
59	  alt: string | null;
60	  href: string | null;
61	  imgSrc: string | null;
62	  childCount: number;
63	  rect: { x: number; y: number; w: number; h: number };
64	  label: string;
65	};
66	
67	export type AgentMessage =
68	  | { ns: string; type: "ready" }
69	  | { ns: string; type: "mode"; on: boolean }
70	  | { ns: string; type: "cleared" }
71	  | { ns: string; type: "selected"; el: SelectedElement };
72	
73	export type SelectionMove = "up" | "down" | "prev" | "next";
