75	// ---------------------------------------------------------------------------
76	// Content Security Policy for the assembled document.
77	//
78	// The served preview route sends its policy as a RESPONSE HEADER. A `srcdoc`
79	// document has no response, so the policy has to travel in-band. It is placed
80	// as the first child of <head>, before any inlined style or script, because a
81	// meta policy only governs what is parsed after it.
82	//
83	// This is STRICTER than the header policy it stands in for, not weaker: the
84	// document is fully self-contained, so nothing needs to be fetched and
85	// `default-src 'none'` costs nothing. `connect-src 'none'`, `form-action`,
86	// `base-uri` and `object-src` are all carried over. Verified in Chrome: an
87	// external <script src> is blocked and never requested, and fetch() rejects.
88	//
89	// `frame-ancestors` is deliberately absent — it is ignored in a meta policy,
90	// and the frame's parent is our own editor page anyway.
91	// ---------------------------------------------------------------------------
92	export const PREVIEW_META_CSP = [
93	  "default-src 'none'",
94	  "style-src 'unsafe-inline'",
95	  "script-src 'unsafe-inline'",
96	  "img-src data:",
97	  "font-src data:",
98	  "connect-src 'none'",
99	  "form-action 'none'",
100	  "base-uri 'none'",
101	  "object-src 'none'",
102	].join("; ");
103	
104	// ---------------------------------------------------------------------------
105	// The agent, as source text. It runs INSIDE the preview, alongside generated
106	// code, so it keeps to boring ES5-shaped JS and namespaces its own DOM with
107	// `data-kodely-ui` so it can never select itself.
108	//
109	// It must not contain the character sequence that would close a script tag;
110	// inlineScript() below escapes that anyway, but keeping it out is cheaper than
