112	// ---------------------------------------------------------------------------
113	const AGENT_SOURCE = `
114	(function () {
115	  var NS = ${JSON.stringify(PREVIEW_NS)};
116	  var mode = false;
117	  var current = null;
118	  var box = null;
119	  var label = null;
120	  var sink = null;
121	
122	  function send(msg) {
123	    msg.ns = NS;
124	    try { parent.postMessage(msg, "*"); } catch (err) {}
125	  }
126	
127	  function clean(s) { return (s || "").replace(/\\s+/g, " ").trim(); }
128	
129	  function isOurs(el) {
130	    return !!(el && el.closest && el.closest("[data-kodely-ui]"));
131	  }
132	
133	  function ensureOverlay() {
134	    if (box || !document.body) return;
135	    box = document.createElement("div");
136	    box.setAttribute("data-kodely-ui", "1");
137	    box.style.cssText = "position:fixed;z-index:2147483647;pointer-events:none;" +
138	      "border:2px solid #1d4ed8;background:rgba(29,78,216,0.08);border-radius:2px;display:none";
139	    label = document.createElement("div");
140	    label.setAttribute("data-kodely-ui", "1");

