"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";
import { Mark } from "@/components/marketing/Logo";
import { AIProgress } from "@/components/ui/AIProgress";
import { Badge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import BuildRating from "./BuildRating";
import { buildSteps, type BuildRun } from "./build-steps";

// The conversation half of the builder. An assistant, not a log file: a named
// header with a real status, the turns so far, and — while a build runs — the
// same step list the preview is showing, driven by the same object.
//
// It owns exactly one aria-live region on this screen (AIProgress's). Nothing
// else here announces, which is why BuildingOverlay, BuildVeil, DiffView and
// SelectionPanel all stay silent: two regions carrying the same text made a
// screen reader read every progress line twice.

export type AssistantState = "ready" | "working" | "error";

export type Applied = {
  buildId: string;
  filesWritten: number;
  credits: number;
  /** Rule 4 of the anti-bill-shock contract: a compile repair is our mistake
      and our cost. The route sends both fields; showing them is the only way
      the customer learns the fixing part was free. */
  repairWaived: boolean;
  waivedCredits: number;
};

export type Suggestion = { id: string; label: string; prompt: string };

function Who({ children }: { children: ReactNode }) {
  return <p className="k-label mb-1.5">{children}</p>;
}

export function AssistantStatus({ state }: { state: AssistantState }) {
  if (state === "working") {
    return (
      <Badge tone="brand" dot pulse>
        Working
      </Badge>
    );
  }
  if (state === "error") {
    return (
      <Badge tone="danger" dot>
        Error
      </Badge>
    );
  }
  return (
    <Badge tone="ok" dot>
      Ready
    </Badge>
  );
}

export default function ChatLog({
  state,
  messages,
  streamingReply,
  run,
  applied,
  onOpenDiff,
  onRegenerate,
  regenerateReason,
  error,
  onRetry,
  onDismissError,
  interruption,
  suggestions,
  onUseSuggestion,
  isFirstBuild,
}: {
  state: AssistantState;
  messages: { role: string; content: string }[];
  /** The assistant's reply as it streams in. Dropped rather than kept if the
      build does not finish — the route only persists it in the success
      branch, so leaving it on screen would show a message a reload deletes. */
  streamingReply: string | null;
  run: BuildRun | null;
  /** The build that just finished IN THIS SESSION. Not restored on reload:
      rating and "see what changed" for a build you last saw yesterday is
      guesswork. */
  applied: Applied | null;
  onOpenDiff: (buildId: string) => void;
  /** Undo the last build and run its prompt again. Null when that would not
      be a truthful offer — see the reason beside it. */
  onRegenerate: (() => void) | null;
  regenerateReason: string;
  error: string | null;
  onRetry: (() => void) | null;
  onDismissError: () => void;
  interruption: ReactNode;
  suggestions: Suggestion[];
  onUseSuggestion: (s: Suggestion) => void;
  isFirstBuild: boolean;
}) {
  const scroller = useRef<HTMLDivElement>(null);
  const end = useRef<HTMLDivElement>(null);
  // Stick to the bottom, but only while the reader is already there. Yanking
  // someone back down while they are re-reading an earlier turn is the single
  // most annoying thing a chat panel can do.
  const stuck = useRef(true);

  useEffect(() => {
    const el = scroller.current;
    if (!el) return;
    const onScroll = () => {
      stuck.current = el.scrollHeight - el.scrollTop - el.clientHeight < 64;
    };
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => el.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    if (stuck.current) end.current?.scrollIntoView({ block: "end" });
  }, [messages.length, streamingReply, run, applied, error, interruption]);

  return (
    <div className="flex min-h-0 flex-col bg-surface">
      <div className="flex shrink-0 items-center justify-between gap-3 border-b border-hair px-4 py-3">
        <span className="flex min-w-0 items-center gap-2">
          <Mark size={20} />
          <span className="k-h2 truncate text-ink">Kodely AI</span>
        </span>
        <AssistantStatus state={state} />
      </div>

      <div ref={scroller} className="min-h-0 flex-1 space-y-4 overflow-y-auto px-4 py-4">
        {messages.length === 0 && (
          <div className="k-msg-in">
            <p className="text-sm leading-relaxed text-ink-2">
              Tell me what you want and I’ll build it — a real React site, live in a minute or
              two. The more specific you are about audience, purpose and tone, the closer the
              first version lands.
            </p>
          </div>
        )}

        {messages.map((m, i) =>
          m.role === "user" ? (
            <div key={i} className="k-msg-in">
              <Who>You</Who>
              <div className="rounded-lg rounded-tl-sm bg-surface-2 px-3 py-2.5 text-sm leading-relaxed whitespace-pre-wrap text-ink">
                {m.content}
              </div>
            </div>
          ) : (
            <div key={i} className="k-msg-in">
              <Who>Kodely</Who>
              <div className="text-sm leading-relaxed whitespace-pre-wrap text-ink-2">
                {m.content}
              </div>
            </div>
          ),
        )}

        {/* The reply as it arrives. The model is told to write the files first
            and finish with two or three sentences, so this usually lands at
            the very end of a build — but on the api engine it can also narrate
            between tool calls, and every one of those characters is part of
            what gets saved, so showing them live is showing the truth. */}
        {streamingReply != null && streamingReply.length > 0 && (
          <div className="k-msg-in">
            <Who>Kodely</Who>
            <div className="text-sm leading-relaxed whitespace-pre-wrap text-ink-2">
              {streamingReply}
            </div>
          </div>
        )}

        {run && run.outcome === "running" && (
          <div className="k-msg-in rounded-lg border border-hair bg-surface-2/60 p-3">
            <AIProgress steps={buildSteps(run)} />
          </div>
        )}

        {applied && (
          <div className="k-msg-in rounded-lg border border-hair bg-surface p-3 shadow-e1">
            <div className="flex flex-wrap items-center gap-2">
              <Badge tone="ok" dot>
                Applied
              </Badge>
              <span className="k-num text-[0.75rem] text-ink-2">
                {applied.filesWritten} file{applied.filesWritten === 1 ? "" : "s"} ·{" "}
                {applied.credits} credit{applied.credits === 1 ? "" : "s"}
              </span>
            </div>
            {applied.repairWaived && (
              // The customer watched "That didn't compile — fixing it" go past.
              // Without this the next thing they see is a charge and no
              // statement that the fixing part was on us.
              <p className="mt-2 text-[0.75rem] leading-relaxed text-ink-2">
                The first compile failed and Kodely fixed it. That repair cost{" "}
                <span className="k-num">{applied.waivedCredits}</span> credits and you weren’t
                charged for it.
              </p>
            )}
            <div className="mt-2.5 flex flex-wrap items-center gap-1.5">
              <Button size="xs" onClick={() => onOpenDiff(applied.buildId)}>
                See what changed
              </Button>
              <Button
                size="xs"
                variant="ghost"
                onClick={() => onRegenerate?.()}
                disabled={onRegenerate === null}
                // Spelled out, because this control does two chargeable-adjacent
                // things: it undoes (free) and then builds again (not free).
                title={
                  onRegenerate
                    ? "Undo this build, then run the same prompt again. The new build is charged; undoing does not refund this one."
                    : regenerateReason
                }
              >
                Try again differently
              </Button>
            </div>
            {onRegenerate === null && (
              <p className="mt-1.5 text-[0.6875rem] text-ink-3">{regenerateReason}</p>
            )}
            <div className="mt-3 border-t border-hair pt-2.5">
              <BuildRating key={applied.buildId} buildId={applied.buildId} />
            </div>
          </div>
        )}

        {interruption}

        {error && (
          <div
            role="alert"
            className="k-msg-in rounded-lg border border-danger/30 bg-danger-tint p-3"
          >
            <p className="text-[0.8125rem] leading-relaxed text-danger">{error}</p>
            <div className="mt-2.5 flex flex-wrap gap-1.5">
              {onRetry && (
                <Button size="xs" onClick={onRetry}>
                  Try again
                </Button>
              )}
              <Button size="xs" variant="ghost" onClick={onDismissError}>
                Dismiss
              </Button>
            </div>
            {onRetry && (
              // Verified in app/api/generate/route.ts: every failure path
              // writes creditsCharged: 0 and never touches the ledger.
              <p className="mt-1.5 text-[0.6875rem] text-ink-2">
                The failed build cost you nothing. Trying again starts a new one, which is
                charged normally.
              </p>
            )}
          </div>
        )}

        {/* Follow-ups. Plain prompt text that lands in the box for editing —
            nothing here is generated, and nothing sends on its own. */}
        {suggestions.length > 0 && (
          <div className="k-msg-in">
            <p className="k-label mb-2">{isFirstBuild ? "Try one of these" : "Next, you could"}</p>
            <div className="flex flex-wrap gap-1.5">
              {suggestions.map((s) => (
                <button
                  key={s.id}
                  type="button"
                  onClick={() => onUseSuggestion(s)}
                  className="k-focus rounded-full border border-hair bg-surface px-2.5 py-1 text-left text-[0.75rem] text-ink-2 transition-colors duration-[var(--t-1)] hover:border-line-mid hover:bg-surface-2 hover:text-ink"
                >
                  {s.label}
                </button>
              ))}
            </div>
          </div>
        )}

        <div ref={end} />
      </div>
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import type { ReactNode, RefObject } from "react";
import { Button, IconButton } from "@/components/ui/Button";
import { Textarea } from "@/components/ui/Field";
import CostEstimate, { type CreditRange } from "./CostEstimate";

// The prompt box and everything that belongs to the act of asking for a change.
//
// EVERY CONTROL HERE IS REAL. What was considered and left out, and why:
//
//  * Attaching a non-image file. There is no multipart handler, no object
//    store and no path by which a .pdf or a .zip could reach the model —
//    app/api/generate/route.ts reads a JSON body and accepts exactly one
//    optional field, `image`, matched against
//    /^data:(image\/(?:png|jpeg|webp));base64,(.+)$/ and silently dropped
//    otherwise. So the picker accepts images only and says so.
//  * A voice button. Nothing transcribes.
//  * "Save as draft" / "queue this change". The route runs one build per
//    request, synchronously, over an open stream. There is no queue.
//
// Stop IS real and is not a UI trick: aborting the fetch closes the response
// body, which fires cancel() on the route's ReadableStream, which aborts the
// in-flight model request server-side. The build row is then written FAILED
// with creditsCharged: 0. See the comment block in BuildInterrupted.tsx.

// Downscale + re-encode client-side, the same treatment the homepage prompt
// gives a reference image: a phone photo is several megabytes of JSON body and
// a large number of vision tokens, and a reference only needs to be legible.
// toDataURL("image/jpeg") produces exactly the `data:image/jpeg;base64,` shape
// the route's regex accepts.
async function downscaleImage(file: File, maxDim = 1400, quality = 0.82): Promise<string> {
  const bitmap = await createImageBitmap(file);
  const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
  const canvas = document.createElement("canvas");
  canvas.width = Math.round(bitmap.width * scale);
  canvas.height = Math.round(bitmap.height * scale);
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("This browser can’t resize the image.");
  ctx.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL("image/jpeg", quality);
}

export default function Composer({
  value,
  onChange,
  promptRef,
  onSubmit,
  onStop,
  busy,
  stopping,
  isFirstBuild,
  balance,
  estimate,
  avgBuildCredits,
  measuredBuilds,
  image,
  onImageChange,
  enhancing,
  onEnhance,
  enhancedFrom,
  onRevertEnhance,
  before,
}: {
  value: string;
  onChange: (v: string) => void;
  promptRef: RefObject<HTMLTextAreaElement | null>;
  onSubmit: () => void;
  onStop: () => void;
  busy: boolean;
  stopping: boolean;
  isFirstBuild: boolean;
  balance: number;
  estimate: CreditRange;
  avgBuildCredits: number;
  measuredBuilds: number;
  /** A data: URL, already downscaled. Null when nothing is attached. */
  image: string | null;
  onImageChange: (image: string | null) => void;
  enhancing: boolean;
  onEnhance: () => void;
  /** The prompt as typed, held while an expanded spec sits in the box. */
  enhancedFrom: string | null;
  onRevertEnhance: () => void;
  /** Undo/redo and the selection panel — rendered above the box because both
      describe the change that is about to be typed. */
  before?: ReactNode;
}) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [imageError, setImageError] = useState<string | null>(null);
  const specMode = enhancedFrom !== null;

  async function pickImage(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    // Reset immediately: picking the same file twice in a row fires no change
    // event otherwise, which reads as the button being broken.
    e.target.value = "";
    if (!file) return;
    if (!file.type.startsWith("image/")) {
      setImageError("Kodely can only look at images — PNG, JPEG or WebP.");
      return;
    }
    setImageError(null);
    try {
      onImageChange(await downscaleImage(file));
    } catch (err) {
      setImageError(err instanceof Error ? err.message : "Couldn’t read that image.");
    }
  }

  return (
    <div className="shrink-0 border-t border-hair bg-surface px-3 pt-2.5 pb-3">
      {before}

      {specMode && (
        <div className="mb-2 flex items-center justify-between gap-2 rounded-md bg-brand-tint px-2.5 py-1.5 text-[0.75rem] text-brand-ink dark:text-brand">
          <span>Expanded spec — edit it before building</span>
          <button
            type="button"
            onClick={onRevertEnhance}
            className="k-focus shrink-0 rounded-sm font-medium underline underline-offset-2"
          >
            Revert
          </button>
        </div>
      )}

      {image && (
        <div className="mb-2 flex items-center gap-2.5 rounded-md border border-hair bg-surface-2 p-2">
          {/* A local data: URL of the user's own file. next/image adds nothing
              here — there is no remote host, no layout shift to prevent and no
              format to negotiate. */}
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={image}
            alt="Attached reference"
            className="size-10 shrink-0 rounded-sm object-cover"
          />
          <div className="min-w-0 flex-1">
            <p className="text-[0.75rem] font-medium text-ink">Reference image attached</p>
            <p className="text-[0.6875rem] text-ink-3">
              Sent with this build as visual guidance.
            </p>
          </div>
          <IconButton
            label="Remove the attached image"
            size="xs"
            onClick={() => onImageChange(null)}
          >
            <svg viewBox="0 0 24 24" className="size-3.5" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round">
              <path d="m6 6 12 12M18 6 6 18" />
            </svg>
          </IconButton>
        </div>
      )}

      {imageError && <p className="mb-2 text-[0.6875rem] text-danger">{imageError}</p>}

      <Textarea
        id="kodely-prompt"
        ref={promptRef}
        aria-label={isFirstBuild ? "Describe the site you want" : "Describe a change"}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={(e) => {
          // Cmd/Ctrl-Enter always builds — including while a spec is on screen,
          // where plain Enter has been handed to the editor.
          if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
            e.preventDefault();
            onSubmit();
            return;
          }
          // Enter sends a one-liner, but while a spec is on screen this box is
          // a multi-line editor — there, Enter has to make a newline or the
          // first paragraph break the user types starts a build of a
          // half-edited spec.
          if (e.key === "Enter" && !e.shiftKey && !specMode) {
            e.preventDefault();
            onSubmit();
          }
        }}
        placeholder={
          isFirstBuild
            ? "Describe the site you want — who it’s for, what it’s selling, how it should feel"
            : "Ask Kodely to change anything…"
        }
        // A ~200-word spec in a three-row box is unreviewable, and an
        // unreviewed spec defeats the point of showing one.
        rows={specMode ? 12 : 3}
        className="resize-none"
      />

      {/* Plan before spend. Hidden while a build runs: the copy describes the
          NEXT build, and leaving it up would relabel the running build's cost
          mid-flight. */}
      {!busy && (
        <div className="mt-2">
          <CostEstimate
            id="kodely-cost-estimate"
            kind={isFirstBuild ? "create" : "edit"}
            range={estimate}
            balance={balance}
            avgBuildCredits={avgBuildCredits}
            measuredBuilds={measuredBuilds}
          />
        </div>
      )}

      <div className="mt-2 flex items-center gap-1.5">
        <input
          ref={fileRef}
          type="file"
          accept="image/png,image/jpeg,image/webp"
          className="hidden"
          onChange={pickImage}
        />
        <IconButton
          label="Attach a reference image"
          size="sm"
          variant="ghost"
          disabled={busy}
          onClick={() => fileRef.current?.click()}
          className="border border-hair"
        >
          <svg viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
            <rect x="3" y="4" width="18" height="16" rx="2" />
            <circle cx="8.5" cy="9.5" r="1.5" />
            <path d="m4 17 5-5 4.5 4.5L16 14l4 4" />
          </svg>
        </IconButton>

        <Button
          size="sm"
          variant="ghost"
          onClick={onEnhance}
          loading={enhancing}
          disabled={busy || !value.trim()}
          title="Expand this into a fuller spec you can read and edit before spending anything"
          className="border border-hair"
        >
          Enhance
        </Button>

        {busy ? (
          <Button
            size="sm"
            variant="secondary"
            className="flex-1"
            onClick={onStop}
            disabled={stopping}
            title="Cancel this build — you won’t be charged for it"
          >
            {stopping ? "Stopping…" : "Stop"}
          </Button>
        ) : (
          <Button
            // The one gradient fill in the builder. The customer's repeated
            // action here is asking for a change, not publishing — Publish in
            // the header is deliberately secondary so this stays the only
            // primary in the view.
            size="sm"
            variant="primary"
            className="flex-1"
            onClick={onSubmit}
            disabled={!value.trim()}
            // Reads the estimate out when the button takes focus, which is how
            // the warning reaches a screen reader without a second aria-live
            // region competing with the progress list.
            aria-describedby="kodely-cost-estimate"
          >
            {isFirstBuild ? "Build site" : "Apply change"}
          </Button>
        )}
      </div>
    </div>
  );
}

"use client";

import { Badge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import { EmptyState } from "@/components/ui/EmptyState";

// Version history. Every row is a real, restorable checkpoint — a successful
// build whose `filesSnapshot` still exists.
//
// TWO TRUTHS THIS PANEL HAS TO CARRY, because getting either wrong turns a
// safety net into a trap:
//
//  1. HISTORY IS BOUNDED. lib/retention.ts clears `filesSnapshot` on any build
//     that is BOTH past the newest 20 for its project AND older than 30 days
//     (SNAPSHOT_KEEP_PER_PROJECT = 20, SNAPSHOT_MIN_AGE_DAYS = 30). Both the
//     server list route and page.tsx filter on the snapshot surviving, so a
//     cleared checkpoint stops appearing rather than sitting here as a row
//     that 404s when clicked. The footnote says so out loud, because "my
//     history only goes back so far" is otherwise discovered as a bug.
//  2. RESTORING IS NOT A REFUND. It writes an old tree back over the draft.
//     It does not cancel the build it steps over, does not return its credits
//     and does not un-publish anything. It is itself free — see the restore
//     route — and that is a different claim.
//
// WHAT IS NOT HERE, because it does not exist: an arbitrary A-vs-B compare.
// loadBuildDiff() answers exactly one question — what did THIS build change
// against the newest earlier surviving checkpoint — so "Compare" is offered as
// that, and DiffView names the checkpoint it compared against.

export type BuildCheckpoint = {
  id: string;
  prompt: string;
  createdAt: string;
  filesWritten: number;
};

/** Only rendered after a click (the panel is never the first view), so a
    relative time cannot cause a hydration mismatch. */
function ago(iso: string): string {
  const ms = Date.now() - new Date(iso).getTime();
  const mins = Math.round(ms / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins} min ago`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `${hours} hour${hours === 1 ? "" : "s"} ago`;
  const days = Math.round(hours / 24);
  return `${days} day${days === 1 ? "" : "s"} ago`;
}

export default function HistoryPanel({
  builds,
  cursor,
  dirty,
  restoring,
  busy,
  onOpenDiff,
  onRestore,
}: {
  builds: BuildCheckpoint[];
  /** The checkpoint the draft currently matches, when we know it. */
  cursor: string | null;
  /** Something unversioned (a Brand or SEO save) sits on top of the cursor. */
  dirty: boolean;
  restoring: string | null;
  busy: boolean;
  onOpenDiff: (buildId: string) => void;
  onRestore: (build: BuildCheckpoint) => void;
}) {
  return (
    <div className="h-full overflow-y-auto bg-canvas p-4 sm:p-6">
      <div className="mx-auto max-w-3xl">
        <h2 className="k-h1 text-ink">Version history</h2>
        <p className="mt-1 max-w-prose text-sm leading-relaxed text-ink-2">
          Every successful build is a restore point. Restoring writes that
          version back over your draft — it doesn’t cancel anything that came after it, and it
          doesn’t refund the credits those builds cost. Restoring itself is free.
        </p>

        {builds.length === 0 ? (
          <EmptyState
            className="mt-6"
            kind="empty"
            title="No checkpoints yet"
            body="The first successful build becomes your first restore point."
          />
        ) : (
          <>
            <ul className="mt-5 flex flex-col gap-2">
              {builds.map((b, i) => {
                const here = b.id === cursor;
                return (
                  <li
                    key={b.id}
                    className={[
                      "rounded-lg border bg-surface p-3 shadow-e1 transition-colors duration-[var(--t-1)]",
                      here ? "border-brand/45" : "border-hair",
                    ].join(" ")}
                  >
                    <div className="flex flex-wrap items-start justify-between gap-3">
                      <div className="min-w-0 flex-1">
                        <div className="flex flex-wrap items-center gap-1.5">
                          {i === 0 && <Badge tone="neutral">Latest</Badge>}
                          {here && (
                            <Badge tone="brand" dot>
                              {dirty ? "Your draft came from here" : "Your draft is here"}
                            </Badge>
                          )}
                          {/* A real, stable identifier rather than an invented
                              "v7": the list is pruned, so a sequence number
                              counted from what survives would silently
                              renumber itself as old snapshots are cleared. */}
                          <span className="k-num font-mono text-[0.6875rem] text-ink-3">
                            {b.id.slice(0, 7)}
                          </span>
                        </div>
                        <p className="mt-1.5 text-sm leading-snug text-ink">{b.prompt}</p>
                        <p className="k-num mt-1 text-[0.75rem] text-ink-3">
                          <time
                            dateTime={b.createdAt}
                            title={new Date(b.createdAt).toLocaleString()}
                          >
                            {ago(b.createdAt)}
                          </time>{" "}
                          · {b.filesWritten} file{b.filesWritten === 1 ? "" : "s"} touched
                        </p>
                      </div>
                      <div className="flex shrink-0 flex-wrap items-center gap-1.5">
                        <Button
                          size="xs"
                          variant="ghost"
                          className="border border-hair"
                          onClick={() => onOpenDiff(b.id)}
                          aria-label={`See what the build “${b.prompt}” changed`}
                        >
                          {i === builds.length - 1 ? "View files" : "Compare"}
                        </Button>
                        <Button
                          size="xs"
                          onClick={() => onRestore(b)}
                          loading={restoring === b.id}
                          disabled={busy || (here && !dirty)}
                          title={
                            here && !dirty
                              ? "Your draft already matches this checkpoint"
                              : "Write this version back over your draft"
                          }
                        >
                          Restore
                        </Button>
                      </div>
                    </div>
                  </li>
                );
              })}
            </ul>

            <p className="mt-4 max-w-prose text-[0.75rem] leading-relaxed text-ink-3">
              History is bounded on purpose. Kodely always keeps the{" "}
              <span className="k-num">20</span> most recent checkpoints for a project; anything
              older than that <em>and</em> more than <span className="k-num">30</span> days old
              has its files cleared to save storage and drops off this list. Nothing you can see
              here has been cleared — a checkpoint that can’t restore is never shown.
            </p>
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/Button";
