import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import StandalonePreview from "./StandalonePreview";

export const dynamic = "force-dynamic";

// "Open in a new tab", for a DRAFT.
//
// This route exists because the obvious target does not work. /api/preview/<id>
// /index.html renders fine inside the editor's iframe only because the editor
// fetches its assets itself and inlines them (see preview-agent.ts). Opened as
// a top-level tab it would ask the browser to load the <script src="/assets/…">
// that Vite emitted — an absolute path, resolved against the APP origin, where
// there is no /assets route. The page would load and then render nothing.
//
// A blob: URL of the assembled document was considered and rejected outright: a
// blob inherits the creating page's origin, which would put generated customer
// JavaScript on the app's own origin with access to same-origin fetches. The
// whole reason the editor's iframe omits `allow-same-origin` is to prevent
// exactly that. A data: URL is a non-starter too — top-level navigation to
// data: is blocked in every current browser.
//
// So: a real page, owner-only like the API it reads, that assembles the same
// self-contained document and hands it to the same kind of sandboxed frame.
// The published site needs none of this and is linked to directly.
export default async function ProjectPreviewPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");
  const { id } = await params;

  const project = await db.project.findFirst({
    where: { id, userId: user.id },
    select: { id: true, name: true },
  });
  if (!project) redirect("/dashboard");

  return <StandalonePreview projectId={project.id} projectName={project.name} />;
}

"use client";

import { useEffect, useState } from "react";
import { Badge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import { ButtonLink } from "@/components/ui/Button";
import { EmptyState } from "@/components/ui/EmptyState";
import { Spinner } from "@/components/ui/Spinner";
import { buildPreviewDocument } from "../preview-agent";

// The full-tab draft preview. Same assembly as the editor's pane and the same
// sandbox — `allow-scripts allow-forms`, never `allow-same-origin`, because
// this document is generated customer code and this page is on our origin.
//
// A thin bar rather than none: without it there is nothing on screen saying
// this is an unpublished draft, and a full-bleed page that looks exactly like
// a live site is the sort of thing people screenshot and send to a client.

export default function StandalonePreview({
  projectId,
  projectName,
}: {
  projectId: string;
  projectName: string;
}) {
  const [doc, setDoc] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [nonce, setNonce] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    const base = `/api/preview/${projectId}`;
    setLoading(true);
    setError(null);

    (async () => {
      try {
        const res = await fetch(`${base}/index.html`, {
          signal: controller.signal,
          cache: "no-store",
        });
        if (!res.ok) throw new Error("The preview could not be loaded.");
        // `missing` is dropped here on purpose. The editor reports it because
        // it is where you would act on it; this tab is for looking at the
        // page, and a warning strip over someone's site is not what they
        // opened a clean tab for.
        const built = await buildPreviewDocument(await res.text(), async (path) => {
          const asset = await fetch(`${base}/${path}`, {
            signal: controller.signal,
            cache: "no-store",
          });
          return asset.ok ? await asset.text() : null;
        });
        if (controller.signal.aborted) return;
        setDoc(built.doc);
      } catch (err) {
        if (controller.signal.aborted) return;
        setError(err instanceof Error ? err.message : "The preview could not be loaded.");
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    })();

    return () => controller.abort();
  }, [projectId, nonce]);

  return (
    <div className="flex h-dvh flex-col bg-canvas">
      <div className="flex shrink-0 flex-wrap items-center gap-2 border-b border-hair bg-surface px-3 py-2">
        <Badge tone="neutral" dot>
          Draft preview
        </Badge>
        <span className="min-w-0 flex-1 truncate text-[0.8125rem] text-ink-2">{projectName}</span>
        <Button size="xs" variant="ghost" className="border border-hair" onClick={() => setNonce((n) => n + 1)}>
          Reload
        </Button>
        <ButtonLink size="xs" href={`/projects/${projectId}`}>
          Back to the editor
        </ButtonLink>
      </div>

      <div className="min-h-0 flex-1 bg-inset">
        {error ? (
          <div className="grid h-full place-items-center p-6">
            <EmptyState
              kind="unavailable"
              title="Nothing to preview"
              body={error}
              action={
                <ButtonLink size="sm" href={`/projects/${projectId}`}>
                  Back to the editor
                </ButtonLink>
              }
            />
          </div>
        ) : doc === null ? (
          <div className="flex h-full items-center justify-center gap-2 text-sm text-ink-3">
            {loading && <Spinner size={16} />}
            {loading ? "Assembling the preview…" : "Nothing built yet."}
          </div>
        ) : (
          <iframe
            key={nonce}
            srcDoc={doc}
            sandbox="allow-scripts allow-forms"
            title={`Draft preview of ${projectName}`}
            className="h-full w-full border-0 bg-white"
          />
        )}
      </div>
    </div>
  );
}

